const multer = require('multer');
const upload = multer({ storage: multer.memoryStorage() });

router.post('/api/kyc/passport/upload', authenticateToken, upload.single('document'), async (req, res) => {
  if (!req.file) return res.status(400).send('No file uploaded');

  const targetUserId = req.user.id;
  const s3Key = `kyc/${targetUserId}/passport_${Date.now()}.jpg`;
  await s3.putObject({
    Bucket: process.env.KYC_BUCKET,
    Key: s3Key,
    Body: req.file.buffer,
    ContentType: req.file.mimetype
  }).promise();

  await UserKycRecord.findOneAndUpdate(
    { userId: targetUserId },
    { passportScanKey: s3Key, kycStatus: 'DOCUMENTS_SUBMITTED' },
    { upsert: true }
  );

  res.json({ success: true, targetUserId, s3Key });
});
